const app=document.getElementById('app');
const modalRoot=document.getElementById('modalRoot');
const toastRoot=document.getElementById('toastRoot');
const state={user:null,role:null,view:'dashboard',courses:[],sections:[],config:{borrowingDays:7,borrowingLimit:3},bookCache:[],report:null,loginLockUntil:0,lockTimer:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const fmtDate=v=>v?new Date(v).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'—';
const fmtDateTime=v=>v?new Date(v).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const fmtLong=v=>v?new Date(v).toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'}):'—';
async function api(url,opt={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let data={};try{data=await r.json()}catch{}if(!r.ok){const e=new Error(data.error||'Request failed');Object.assign(e,data);throw e}return data}
function toast(message,type='info'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;toastRoot.appendChild(el);setTimeout(()=>el.remove(),3500)}
function openModal(title,body,footer=''){modalRoot.innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div></div>`;document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()})}
function closeModal(){modalRoot.innerHTML=''}
window.closeModal=closeModal;
function icon(name){return ({dashboard:'▦',books:'▤',borrowers:'♙',transactions:'↔',reports:'▥',clients:'♚',settings:'⚙',browse:'⌕',history:'◫',profile:'●',logout:'↪'})[name]||'•'}
function shell(role,content){const owner=role==='owner';app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-row"><div class="brand-mark">▥</div><div><div class="brand-name">Libra<span>Tech</span></div><div class="brand-sub">LIBRARY MANAGEMENT</div></div></div></div><div class="role-pill">${owner?'OWNER':'CLIENT'}</div><div class="nav-title">Main</div><nav class="nav">${(owner?[['dashboard','Dashboard'],['books','Books'],['borrowers','Borrowers'],['transactions','Borrow / Return'],['reports','Reports'],['clients','Client Accounts'],['settings','Settings']]:[['dashboard','Dashboard'],['browse','Browse Books'],['history','My Borrowings'],['profile','My Profile']]).map(([k,t])=>`<button class="${state.view===k?'active':''}" onclick="navigate('${k}')"><i>${icon(k)}</i>${t}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav" style="width:100%;border:0;background:transparent;color:#c7d0dd;text-align:left;padding:11px 12px" onclick="logout()"><i>${icon('logout')}</i> Logout</button></div></aside><div class="overlay" id="sideOverlay" onclick="toggleSidebar(false)"></div><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:10px"><button class="hamb" onclick="toggleSidebar(true)">☰</button><div class="crumb">LibraTech <span style="color:#65758e">/</span> ${owner?'Owner':'Client'} ${titleFor(state.view)}</div></div><div class="top-actions"><div class="clock"><div id="clockDate">—</div><strong id="clockTime">—</strong></div><div class="user-chip">${esc(state.user?.fullName||state.user?.username||'User')}</div></div></header><section class="content" id="content">${content}</section></main></div>`;startClock()}
function titleFor(v){return ({dashboard:'Dashboard',books:'Book Collection',borrowers:'Borrowers',transactions:'Borrow / Return',reports:'Reports',clients:'Client Accounts',settings:'Settings',browse:'Browse Books',history:'My Borrowings',profile:'My Profile'})[v]||'Dashboard'}
function toggleSidebar(v){document.getElementById('sidebar')?.classList.toggle('open',v);document.getElementById('sideOverlay')?.classList.toggle('show',v)}
window.toggleSidebar=toggleSidebar;
function startClock(){clearInterval(window.__clock);const tick=()=>{const d=new Date();const a=document.getElementById('clockDate'),b=document.getElementById('clockTime');if(a)a.textContent=fmtLong(d);if(b)b.textContent=d.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit'})};tick();window.__clock=setInterval(tick,1000)}
async function loadBase(){const [courses,sections,config]=await Promise.all([api('/api/courses'),api('/api/sections'),api('/api/config')]);state.courses=courses;state.sections=sections;state.config=config}
async function boot(){try{await loadBase();const m=await api('/api/auth/me');state.user=m.user;state.role=m.user.role;state.view='dashboard';await renderView()}catch{landing()}}
function landing(){app.innerHTML=`<div class="landing"><div class="landing-card"><div class="landing-brand"><div class="brand-mark">▥</div><div><h1>Libra<span>Tech</span></h1><p>COLLEGE LIBRARY MANAGEMENT SYSTEM</p></div></div><div class="choice-grid"><div class="choice"><h2>Owner</h2><p>Manage the library collection, clients, borrowers, transactions, reports, and system settings.</p><button class="btn btn-primary" onclick="ownerLogin()">Owner Login</button></div><div class="choice"><h2>Client</h2><p>Register or sign in to browse the complete college library and manage your own borrowings.</p><button class="btn btn-primary" onclick="clientLogin()">Client Sign In</button><button class="btn btn-ghost" style="margin-left:6px" onclick="registerPage()">Create Account</button></div></div><div class="notice" style="margin-top:18px">LibraTech serves all college courses and academic fields. IT is one category—not the whole library.</div></div></div>`}
function loginLayout(title,subtitle,form,back=true){app.innerHTML=`<div class="login-shell"><div class="login-card">${back?'<button class="back" onclick="landing()">← Back</button>':''}<div class="brand-row" style="margin-bottom:18px"><div class="brand-mark">▥</div><div><div class="brand-name">Libra<span>Tech</span></div><div class="brand-sub">LIBRARY MANAGEMENT</div></div></div><h1>${title}</h1><p>${subtitle}</p>${form}</div></div>`}
function ownerLogin(){loginLayout('Owner Sign In','Administrative access to the college library.',`<div id="ownerLock"></div><form onsubmit="doOwnerLogin(event)"><div class="field" style="margin-bottom:12px"><label>Username</label><input id="ownerUsername" autocomplete="username" required></div><div class="field"><label>Password</label><input id="ownerPassword" type="password" autocomplete="current-password" required></div><div class="form-actions"><button class="btn btn-primary" type="submit" id="ownerSubmit">Sign In</button></div></form><div class="security-note">After 3 incorrect Owner attempts, sign-in is temporarily locked for 30 seconds. Passwords are stored as server-side hashes.</div>`);startOwnerLockUi()}
function startOwnerLockUi(){clearInterval(state.lockTimer);const tick=()=>{const el=document.getElementById('ownerLock');const btn=document.getElementById('ownerSubmit');if(!el||!btn)return clearInterval(state.lockTimer);const left=Math.max(0,Math.ceil((state.loginLockUntil-Date.now())/1000));if(left){el.innerHTML=`<div class="lock-box">Too many failed attempts. Try again in <strong>${left}s</strong>.</div>`;btn.disabled=true}else{el.innerHTML='';btn.disabled=false;clearInterval(state.lockTimer)}};tick();state.lockTimer=setInterval(tick,250)}
async function doOwnerLogin(e){e.preventDefault();try{const r=await api('/api/auth/owner-login',{method:'POST',body:JSON.stringify({username:ownerUsername.value,password:ownerPassword.value})});state.user=r.user;state.role='owner';state.view='dashboard';toast('Owner sign in successful.','success');setTimeout(renderView,160)}catch(err){if(err.locked){state.loginLockUntil=Date.now()+(err.retryAfter||30)*1000;startOwnerLockUi();toast('Owner login is temporarily locked.','warning')}else toast(err.error,'error')}}
function clientLogin(){loginLayout('Client Sign In','Sign in to browse books and view your own borrowing records.',`<form onsubmit="doClientLogin(event)"><div class="field" style="margin-bottom:12px"><label>Username</label><input id="clientUsername" autocomplete="username" required></div><div class="field"><label>Password</label><input id="clientPassword" type="password" autocomplete="current-password" required></div><div class="form-actions"><button class="btn btn-primary" type="submit">Sign In</button><button class="btn btn-ghost" type="button" onclick="registerPage()">Create Account</button></div></form>`)}
async function doClientLogin(e){e.preventDefault();try{const r=await api('/api/auth/client-login',{method:'POST',body:JSON.stringify({username:clientUsername.value,password:clientPassword.value})});state.user=r.user;state.role='client';state.view='dashboard';toast('Welcome to LibraTech.','success');setTimeout(renderView,160)}catch(err){toast(err.error,'error')}}
function registerPage(){const courseOptions=state.courses.map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.name)}</option>`).join('');loginLayout('Create Client Account','Register once, then sign in manually.',`<form onsubmit="doRegister(event)"><div class="form-grid"><div class="field full"><label>Full Name *</label><input id="rFull" required></div><div class="field"><label>Student ID *</label><input id="rStudent" required></div><div class="field"><label>Email *</label><input id="rEmail" type="email" required></div><div class="field"><label>Username *</label><input id="rUser" required></div><div class="field"><label>Course / Program *</label><select id="rCourse" required onchange="updateRegisterSections()"><option value="">Select course</option>${courseOptions}</select></div><div class="field"><label>Year Level *</label><select id="rYear" required><option value="">Select</option><option>1st Year</option><option>2nd Year</option><option>3rd Year</option><option>4th Year</option></select></div><div class="field"><label>Section *</label><select id="rSection" required><option value="">Select course first</option></select></div><div class="field"><label>Password *</label><input id="rPass" type="password" minlength="8" required></div><div class="field"><label>Confirm Password *</label><input id="rConfirm" type="password" minlength="8" required></div></div><div class="form-actions"><button class="btn btn-ghost" type="button" onclick="clientLogin()">Back to Sign In</button><button class="btn btn-primary" type="submit">Create Account</button></div></form>`);updateRegisterSections()}
function updateRegisterSections(){const c=Number(document.getElementById('rCourse')?.value);const s=document.getElementById('rSection');if(!s)return;s.innerHTML='<option value="">Select section</option>'+state.sections.filter(x=>x.course_id===c).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}
async function doRegister(e){e.preventDefault();try{await api('/api/auth/register',{method:'POST',body:JSON.stringify({fullName:rFull.value,studentId:rStudent.value,email:rEmail.value,username:rUser.value,password:rPass.value,confirmPassword:rConfirm.value,courseId:Number(rCourse.value),yearLevel:rYear.value,sectionId:Number(rSection.value)})});toast('Account successfully created. Please sign in.','success');setTimeout(clientLogin,400)}catch(err){toast(err.error,'error')}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}state.user=null;state.role=null;state.view='dashboard';clearInterval(window.__clock);landing()}
window.logout=logout;
async function navigate(view){try{state.view=view;toggleSidebar(false);await renderView()}catch(e){toast(e.error||'Unable to load this page. Please try again.','error')}}
window.navigate=navigate;
async function renderView(){if(!state.user)return landing();if(state.role==='owner')await renderOwner();else await renderClient()}
async function renderOwner(){shell('owner','<div class="empty">Loading dashboard…</div>');const c=document.getElementById('content');if(state.view==='dashboard')c.innerHTML=await ownerDashboard();else if(state.view==='books')c.innerHTML=await ownerBooks();else if(state.view==='borrowers')c.innerHTML=await ownerBorrowers();else if(state.view==='transactions')c.innerHTML=await ownerTransactions();else if(state.view==='reports')c.innerHTML=await ownerReports();else if(state.view==='clients')c.innerHTML=await ownerClients();else if(state.view==='settings')c.innerHTML=await ownerSettings();}
async function ownerDashboard(){const d=await api('/api/dashboard/owner');return `<div class="page-title"><div><h1>Library Dashboard</h1><p>Overview of books, users, borrowing activity, and availability.</p></div><div class="actions"><button class="btn" onclick="printCurrent()">Print Dashboard</button><button class="btn" onclick="downloadDashboard()">Download Dashboard</button></div></div><div class="grid stats"><div class="stat blue" onclick="navigate('books')"><div class="stat-label">Total Titles</div><div class="stat-value">${d.stats.totalBooks}</div><div class="stat-note">Open Book Collection</div></div><div class="stat green" onclick="navigate('books');setTimeout(()=>filterBooks('available'),250)"><div class="stat-label">Available Copies</div><div class="stat-value">${d.stats.availableCopies}</div><div class="stat-note">View available books</div></div><div class="stat amber" onclick="navigate('transactions');setTimeout(()=>filterTransactions('borrowed'),250)"><div class="stat-label">Borrowed Copies</div><div class="stat-value">${d.stats.borrowedCopies}</div><div class="stat-note">Active borrowings</div></div><div class="stat purple" onclick="navigate('borrowers')"><div class="stat-label">Total Borrowers</div><div class="stat-value">${d.stats.totalBorrowers}</div><div class="stat-note">Open borrower records</div></div><div class="stat cyan" onclick="navigate('clients')"><div class="stat-label">Total Clients</div><div class="stat-value">${d.stats.totalClients}</div><div class="stat-note">Client accounts</div></div><div class="stat blue" onclick="navigate('clients');setTimeout(()=>document.getElementById('clientStatus').value='active',250);setTimeout(()=>filterClients(),280)"><div class="stat-label">Active Clients</div><div class="stat-value">${d.stats.activeClients}</div><div class="stat-note">Active accounts</div></div><div class="stat green" onclick="navigate('reports')"><div class="stat-label">Courses Represented</div><div class="stat-value">${d.stats.totalCourses}</div><div class="stat-note">Academic coverage</div></div><div class="stat red" onclick="navigate('transactions');setTimeout(()=>filterTransactions('overdue'),250)"><div class="stat-label">Overdue Books</div><div class="stat-value">${d.stats.overdueBooks}</div><div class="stat-note">Needs attention</div></div></div><div class="grid two"><div class="panel"><div class="panel-head"><h2>Recent Borrowing Activity</h2><button class="btn btn-ghost" onclick="navigate('transactions')">View all</button></div><div class="table-wrap">${txTable(d.transactions,true)}</div></div><div class="panel"><div class="panel-head"><h2>Book Availability Overview</h2><button class="btn btn-ghost" onclick="navigate('books')">Open books</button></div><div class="panel-body">${d.groups.length?d.groups.map(x=>`<div class="activity"><div><strong>${esc(x.field_group)}</strong><div class="mini">${x.book_count} titles</div></div><span>${x.book_count?'Available collection':''}</span></div>`).join(''):'<div class="empty">No book data yet.</div>'}</div></div></div><div class="grid two" style="margin-top:16px"><div class="panel"><div class="panel-head"><h2>Popular Books</h2><button class="btn btn-ghost" onclick="navigate('reports')">Reports</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Title</th><th>Borrowings</th></tr></thead><tbody>${d.popular.map(x=>`<tr><td>${esc(x.title)}</td><td>${x.borrow_count}</td></tr>`).join('')||'<tr><td colspan="2" class="empty">No borrowing transactions yet.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Recent System Activity</h2><button class="btn btn-ghost" onclick="openActivity()">View activity</button></div><div class="panel-body">${d.activities.map(a=>`<div class="activity"><div><strong>${esc(a.action)}</strong><div class="mini">${esc(a.details||'')}</div></div><span>${fmtDateTime(a.created_at)}</span></div>`).join('')||'<div class="empty">No activity yet.</div>'}</div></div></div>`}
function txTable(rows,compact=false){return `<table class="table"><thead><tr><th>Transaction</th><th>Borrower</th><th>Book</th><th>Borrow Date</th><th>Due Date</th><th>Status</th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr onclick="openTransaction(${t.id})" style="cursor:pointer"><td><strong>${esc(t.transaction_code)}</strong></td><td>${esc(t.borrower_name||t.client_name_snapshot)}</td><td>${esc(t.book_title||t.book_title_snapshot)}</td><td>${fmtDate(t.borrow_date)}</td><td>${fmtDate(t.due_date)}</td><td>${statusBadge(t.status)}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No borrowing transactions yet.</td></tr>`}</tbody></table>`}
function statusBadge(s){const cls=s==='returned'?'green':s==='overdue'?'red':s==='borrowed'?'amber':'gray';return `<span class="badge ${cls}">${esc(s)}</span>`}
async function ownerBooks(){const books=await api('/api/books');state.bookCache=books;return `<div class="page-title"><div><h1>Book Collection</h1><p>Manage books from all academic fields and courses.</p></div><div class="actions"><button class="btn" onclick="printBooks()">Print</button><button class="btn" onclick="downloadRows(booksForDownload(),'Library_Book_Inventory')">Download CSV</button><button class="btn btn-primary" onclick="bookForm()">+ Add Book</button></div></div><div class="panel"><div class="panel-body"><div class="searchbar"><input id="bookSearch" placeholder="Search title, author, ISBN, Book ID" oninput="applyBookFilters()"><select id="bookCourse" onchange="applyBookFilters()"><option value="">All Courses</option>${state.courses.map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.name)}</option>`).join('')}</select><select id="bookAvail" onchange="applyBookFilters()"><option value="">All Availability</option><option value="available">Available</option><option value="unavailable">Unavailable</option></select><select id="bookCategory" onchange="applyBookFilters()"><option value="">All Categories</option>${[...new Set(books.map(b=>b.category))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="btn btn-ghost" onclick="document.getElementById('bookSearch').value='';document.getElementById('bookCourse').value='';document.getElementById('bookAvail').value='';document.getElementById('bookCategory').value='';applyBookFilters()">Clear</button></div></div><div class="table-wrap" id="bookTable">${bookTable(books)}</div></div>`}
function bookTable(rows){return `<table class="table"><thead><tr><th>Book ID</th><th>Title</th><th>Author</th><th>Courses</th><th>Category</th><th>Qty</th><th>Available</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.length?rows.map(b=>`<tr><td>${esc(b.book_code)}</td><td class="wrap"><strong>${esc(b.title)}</strong><div class="mini">${esc(b.isbn||'No ISBN')}</div></td><td>${esc(b.author)}</td><td class="wrap">${b.courses.slice(0,2).map(esc).join('<br>')}${b.courses.length>2?'<br>…':''}</td><td>${esc(b.category)}</td><td>${b.quantity}</td><td>${b.available_copies}</td><td>${b.available_copies?'<span class="badge green">Available</span>':'<span class="badge red">Unavailable</span>'}</td><td><button class="btn" onclick="openBook(${b.id})">View</button> <button class="btn" onclick="bookForm(${b.id})">Edit</button></td></tr>`).join(''):'<tr><td colspan="9" class="empty"><strong>No books found.</strong>Try another filter or add a book.</td></tr>'}</tbody></table>`}
let bookTimer;function applyBookFilters(){clearTimeout(bookTimer);bookTimer=setTimeout(async()=>{try{const q=encodeURIComponent(document.getElementById('bookSearch')?.value||'');const course=document.getElementById('bookCourse')?.value||'';const avail=document.getElementById('bookAvail')?.value||'';const cat=document.getElementById('bookCategory')?.value||'';const rows=await api(`/api/books?search=${q}&courseId=${course}&availability=${avail}&category=${encodeURIComponent(cat)}`);const table=document.getElementById('bookTable');if(table)table.innerHTML=bookTable(rows)}catch(e){toast(e.error||'Unable to filter books.','error')}},180)}
function filterBooks(v){if(!document.getElementById('bookAvail'))return;document.getElementById('bookAvail').value=v;applyBookFilters()}
window.filterBooks=filterBooks;window.applyBookFilters=applyBookFilters;
function bookForm(id){const b=id?state.bookCache.find(x=>x.id===id):null;const selected=new Set((b?.courses||[]).map(x=>x.split(' — ')[0]));const courses=state.courses.map(c=>`<label class="check"><input type="checkbox" name="courseIds" value="${c.id}" ${selected.has(c.code)?'checked':''}> ${esc(c.code)} — ${esc(c.name)}</label>`).join('');openModal(id?'Edit Book':'Add Book',`<form id="bookForm"><div class="form-grid"><div class="field"><label>Book ID *</label><input name="bookCode" value="${esc(b?.book_code||'')}" required></div><div class="field"><label>ISBN</label><input name="isbn" value="${esc(b?.isbn||'')}"></div><div class="field full"><label>Title *</label><input name="title" value="${esc(b?.title||'')}" required></div><div class="field"><label>Author *</label><input name="author" value="${esc(b?.author||'')}" required></div><div class="field"><label>Subject Area *</label><input name="subjectArea" value="${esc(b?.subject_area||'')}" required></div><div class="field"><label>Category *</label><input name="category" value="${esc(b?.category||'')}" required></div><div class="field"><label>Publisher</label><input name="publisher" value="${esc(b?.publisher||'')}"></div><div class="field"><label>Publication Year</label><input name="publicationYear" type="number" min="1900" max="2100" value="${esc(b?.publication_year||'')}"></div><div class="field"><label>Quantity *</label><input name="quantity" type="number" min="1" value="${b?.quantity||1}" required></div>${id?`<div class="field"><label>Available Copies *</label><input name="availableCopies" type="number" min="0" max="${b?.quantity||1}" value="${b?.available_copies||0}" required></div>`:''}<div class="field full"><label>Course / Program Relevance</label><div class="check-grid">${courses}</div></div><div class="field full"><label>Description</label><textarea name="description">${esc(b?.description||'')}</textarea></div></div></form>`,`${id?'<button class="btn btn-danger" onclick="deleteBook('+id+')">Delete</button>':''}<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="saveBook(${id||0})">${id?'Save Changes':'Add Book'}</button>`)}
async function saveBook(id){const f=document.getElementById('bookForm');if(!f)return;const fd=new FormData(f);const body=Object.fromEntries(fd.entries());body.courseIds=[...f.querySelectorAll('input[name="courseIds"]:checked')].map(x=>Number(x.value));body.quantity=Number(body.quantity);body.publicationYear=body.publicationYear?Number(body.publicationYear):null;if(id)body.availableCopies=Number(body.availableCopies);try{await api(id?`/api/books/${id}`:'/api/books',{method:id?'PUT':'POST',body:JSON.stringify(body)});closeModal();toast(id?'Book successfully updated.':'Book successfully added.','success');await renderView()}catch(e){toast(e.error,'error')}}
async function deleteBook(id){if(!confirm('Delete this book? This cannot be undone.'))return;try{await api(`/api/books/${id}`,{method:'DELETE'});closeModal();toast('Book successfully deleted.','success');await renderView()}catch(e){toast(e.error,'error')}}
async function openBook(id){const b=await api(`/api/books/${id}`);openModal('Book Information',`<div class="detail-grid"><div class="detail"><small>Book ID</small><strong>${esc(b.book_code)}</strong></div><div class="detail"><small>ISBN</small><strong>${esc(b.isbn||'—')}</strong></div><div class="detail"><small>Title</small><strong>${esc(b.title)}</strong></div><div class="detail"><small>Author</small><strong>${esc(b.author)}</strong></div><div class="detail"><small>Category</small><strong>${esc(b.category)}</strong></div><div class="detail"><small>Subject Area</small><strong>${esc(b.subject_area)}</strong></div><div class="detail"><small>Publisher</small><strong>${esc(b.publisher||'—')}</strong></div><div class="detail"><small>Publication Year</small><strong>${esc(b.publication_year||'—')}</strong></div><div class="detail"><small>Quantity</small><strong>${b.quantity}</strong></div><div class="detail"><small>Available Copies</small><strong>${b.available_copies}</strong></div><div class="detail full"><small>Courses</small><strong>${b.courses.map(esc).join('<br>')||'General library'}</strong></div><div class="detail full"><small>Description</small><strong>${esc(b.description||'No description.')}</strong></div></div>`,state.role==='owner'?`<button class="btn" onclick="closeModal();bookForm(${b.id})">Edit</button><button class="btn" onclick="printBook(${b.id})">Print</button>`:'');}
async function ownerBorrowers(){const rows=await api('/api/borrowers');return `<div class="page-title"><div><h1>Borrowers</h1><p>Manage borrower records across all programs. Client registrations are linked automatically.</p></div><div class="actions"><button class="btn" onclick="printBorrowers()">Print</button><button class="btn" onclick="downloadBorrowers()">Download CSV</button><button class="btn btn-primary" onclick="borrowerForm()">+ Add Borrower</button></div></div><div class="panel"><div class="panel-body"><div class="searchbar"><select id="borrowerCourse" onchange="filterBorrowers()"><option value="">All Courses</option>${state.courses.map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.name)}</option>`).join('')}</select><select id="borrowerStatus" onchange="filterBorrowers()"><option value="">All Status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><div class="table-wrap" id="borrowerTable">${borrowerTable(rows)}</div></div>`}
function borrowerTable(rows){state.borrowerCache=rows;return `<table class="table"><thead><tr><th>Name</th><th>Student ID</th><th>Course</th><th>Year</th><th>Section</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${rows.length?rows.map(b=>`<tr><td><strong>${esc(b.full_name)}</strong><div class="mini">${esc(b.email||'')}</div></td><td>${esc(b.student_id)}</td><td>${esc(b.course_code||'—')}</td><td>${esc(b.year_level||'—')}</td><td>${esc(b.section_name||'—')}</td><td>${b.status==='active'?'<span class="badge green">Active</span>':'<span class="badge red">Inactive</span>'}</td><td>${fmtDate(b.created_at)}</td><td><button class="btn" onclick="borrowerFormById(${b.id})">Edit</button> <button class="btn btn-danger" onclick="deleteBorrower(${b.id})">Delete</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty"><strong>No borrowers found.</strong>Borrower records appear after Clients register.</td></tr>'}</tbody></table>`}
function borrowerFormById(id){const b=(state.borrowerCache||[]).find(x=>x.id===id);borrowerForm(b)}
function borrowerForm(b=null){const courseOptions=state.courses.map(c=>`<option value="${c.id}" ${b?.course_id===c.id?'selected':''}>${esc(c.code)} — ${esc(c.name)}</option>`).join('');const secOptions=state.sections.filter(x=>!b?.course_id||x.course_id===b.course_id).map(x=>`<option value="${x.id}" ${b?.section_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('');openModal(b?'Edit Borrower':'Add Borrower',`<form id="borrowerForm"><div class="form-grid"><div class="field full"><label>Full Name *</label><input name="fullName" value="${esc(b?.full_name||'')}" required></div><div class="field"><label>Student ID *</label><input name="studentId" value="${esc(b?.student_id||'')}" required></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(b?.email||'')}"></div><div class="field"><label>Course</label><select name="courseId" id="bfCourse" onchange="updateBorrowerSections()"><option value="">Select course</option>${courseOptions}</select></div><div class="field"><label>Year Level</label><select name="yearLevel"><option value="">Select</option>${['1st Year','2nd Year','3rd Year','4th Year'].map(x=>`<option ${b?.year_level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Section</label><select name="sectionId" id="bfSection"><option value="">Select course first</option>${secOptions}</select></div><div class="field"><label>Status</label><select name="status"><option value="active" ${!b||b.status==='active'?'selected':''}>Active</option><option value="inactive" ${b?.status==='inactive'?'selected':''}>Inactive</option></select></div></div></form>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="saveBorrower(${b?.id||0})">Save</button>`)}
function updateBorrowerSections(){const c=Number(document.getElementById('bfCourse')?.value);const s=document.getElementById('bfSection');if(!s)return;s.innerHTML='<option value="">Select section</option>'+state.sections.filter(x=>x.course_id===c).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}
async function saveBorrower(id){const f=document.getElementById('borrowerForm');const body=Object.fromEntries(new FormData(f).entries());body.courseId=body.courseId?Number(body.courseId):null;body.sectionId=body.sectionId?Number(body.sectionId):null;try{await api(id?`/api/borrowers/${id}`:'/api/borrowers',{method:id?'PUT':'POST',body:JSON.stringify(body)});closeModal();toast(id?'Borrower successfully updated.':'Borrower successfully added.','success');await renderView()}catch(e){toast(e.error,'error')}}
async function deleteBorrower(id){if(!confirm('Delete this borrower?'))return;try{await api(`/api/borrowers/${id}`,{method:'DELETE'});toast('Borrower successfully deleted.','success');await renderView()}catch(e){toast(e.error,'error')}}
async function filterBorrowers(){const c=document.getElementById('borrowerCourse')?.value||'',s=document.getElementById('borrowerStatus')?.value||'';document.getElementById('borrowerTable').innerHTML=borrowerTable(await api(`/api/borrowers?courseId=${c}&status=${s}`))}
async function ownerClients(){const rows=await api('/api/clients');return `<div class="page-title"><div><h1>Client Accounts</h1><p>Manage registered student accounts. Passwords are never displayed.</p></div><div class="actions"><button class="btn" onclick="printClients()">Print</button><button class="btn" onclick="downloadClients()">Download CSV</button></div></div><div class="panel"><div class="panel-body"><div class="searchbar"><select id="clientCourse" onchange="filterClients()"><option value="">All Courses</option>${state.courses.map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.name)}</option>`).join('')}</select><select id="clientStatus" onchange="filterClients()"><option value="">All Status</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><div class="table-wrap" id="clientTable">${clientTable(rows)}</div></div>`}
function clientTable(rows){return `<table class="table"><thead><tr><th>Client</th><th>Student ID</th><th>Course</th><th>Year / Section</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody>${rows.length?rows.map(c=>`<tr><td><strong>${esc(c.full_name)}</strong><div class="mini">${esc(c.email||'')}</div></td><td>${esc(c.student_id)}</td><td>${esc(c.course_code||'—')}</td><td>${esc(c.year_level||'—')} / ${esc(c.section_name||'—')}</td><td>${c.account_status==='active'?'<span class="badge green">Active</span>':'<span class="badge red">Inactive</span>'}</td><td>${fmtDate(c.created_at)}</td><td><button class="btn" onclick="toggleClient(${c.id},'${c.account_status==='active'?'inactive':'active'}')">${c.account_status==='active'?'Deactivate':'Activate'}</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty"><strong>No registered clients yet.</strong>Client accounts will appear here after students register.</td></tr>'}</tbody></table>`}
async function filterClients(){const c=document.getElementById('clientCourse')?.value||'',s=document.getElementById('clientStatus')?.value||'';document.getElementById('clientTable').innerHTML=clientTable(await api(`/api/clients?courseId=${c}&status=${s}`))}
async function toggleClient(id,status){try{await api(`/api/clients/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});toast(`Client account ${status}.`,'success');await renderView()}catch(e){toast(e.error,'error')}}
async function ownerBorrowForm(){const [borrowers,books]=await Promise.all([api('/api/borrowers?status=active'),api('/api/books?availability=available')]);openModal('Record Borrowing',`<form id="ownerBorrowForm"><div class="form-grid"><div class="field full"><label>Borrower *</label><select name="borrowerId" required><option value="">Select borrower</option>${borrowers.map(b=>`<option value="${b.id}">${esc(b.full_name)} — ${esc(b.student_id)} — ${esc(b.course_code||'')}</option>`).join('')}</select></div><div class="field full"><label>Book *</label><select name="bookId" required><option value="">Select available book</option>${books.map(b=>`<option value="${b.id}">${esc(b.title)} — ${b.available_copies} available</option>`).join('')}</select></div></div></form>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="saveOwnerBorrow()">Confirm Borrow</button>`)}
async function saveOwnerBorrow(){const f=document.getElementById('ownerBorrowForm');const body=Object.fromEntries(new FormData(f).entries());body.borrowerId=Number(body.borrowerId);body.bookId=Number(body.bookId);try{await api('/api/transactions/owner-borrow',{method:'POST',body:JSON.stringify(body)});closeModal();toast('Borrow transaction recorded.','success');await renderView()}catch(e){toast(e.error,'error')}}
async function ownerTransactions(){const initial=await api('/api/transactions?status=all');return `<div class="page-title"><div><h1>Borrow / Return</h1><p>Monitor all active and historical transactions.</p></div><div class="actions"><button class="btn" onclick="printTransactions()">Print</button><button class="btn" onclick="downloadTransactionReport()">Download CSV</button><button class="btn btn-primary" onclick="ownerBorrowForm()">+ Record Borrowing</button></div></div><div class="panel"><div class="panel-body"><div class="searchbar"><select id="txStatus" onchange="filterTransactions(this.value)"><option value="all">All Transactions</option><option value="borrowed">Borrowed</option><option value="overdue">Overdue</option><option value="returned">Returned</option></select><select id="txCourse" onchange="filterTransactions(document.getElementById('txStatus').value)"><option value="">All Courses</option>${state.courses.map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.name)}</option>`).join('')}</select></div></div><div class="table-wrap" id="txTable">${txTable(initial)}</div></div>`}
async function filterTransactions(status='all'){const c=document.getElementById('txCourse')?.value||'';if(document.getElementById('txStatus'))document.getElementById('txStatus').value=status;const rows=await api(`/api/transactions?status=${status}&courseId=${c}`);document.getElementById('txTable').innerHTML=txTable(rows)}
window.filterTransactions=filterTransactions;
async function openTransaction(id){const t=await api(`/api/transactions/${id}`);openModal('Transaction Details',`<div class="detail-grid"><div class="detail"><small>Transaction ID</small><strong>${esc(t.transaction_code)}</strong></div><div class="detail"><small>Status</small><strong>${statusBadge(t.status)}</strong></div><div class="detail"><small>Borrower</small><strong>${esc(t.borrower_name)}</strong></div><div class="detail"><small>Student ID</small><strong>${esc(t.student_id)}</strong></div><div class="detail"><small>Course</small><strong>${esc(t.course_code||t.course_name||'—')}</strong></div><div class="detail"><small>Year / Section</small><strong>${esc(t.year_level||'—')} / ${esc(t.section_name||'—')}</strong></div><div class="detail"><small>Book</small><strong>${esc(t.book_title)}</strong></div><div class="detail"><small>Borrow Date</small><strong>${fmtDateTime(t.borrow_date)}</strong></div><div class="detail"><small>Due Date</small><strong>${fmtDateTime(t.due_date)}</strong></div><div class="detail"><small>Return Date</small><strong>${fmtDateTime(t.return_date)}</strong></div></div>`,state.role==='owner'&&t.status!=='returned'?`<button class="btn btn-success" onclick="returnTransaction(${t.id})">Record Return</button>`:'');}
async function returnTransaction(id){if(!confirm('Record this book as returned?'))return;try{await api(`/api/transactions/${id}/return`,{method:'POST'});closeModal();toast('Book successfully returned.','success');await renderView()}catch(e){toast(e.error,'error')}}
async function ownerReports(){return `<div class="page-title"><div><h1>Reports</h1><p>Generate current database reports across all academic fields.</p></div></div><div class="grid three">${[['inventory','Complete Inventory'],['available','Available Books'],['borrowed','Borrowed Books'],['overdue','Overdue Books'],['clients','Client List'],['course','Borrowing by Course'],['categories','Books by Category'],['popular','Popular Books'],['stats','General Library Statistics']].map(([k,t])=>`<div class="panel"><div class="panel-body"><h3 style="margin-top:0">${t}</h3><p class="mini">Current database information.</p><button class="btn btn-primary" onclick="generateReport('${k}')">Generate</button></div></div>`).join('')}</div><div id="reportArea" style="margin-top:16px"></div>`}
async function generateReport(type){try{const r=await api(`/api/reports?type=${type}`);state.report=r;const area=document.getElementById('reportArea');area.innerHTML=`<div class="panel"><div class="panel-head"><div><h2>${esc(r.title)}</h2><div class="mini">Generated ${fmtDateTime(r.generatedAt)} by ${esc(r.generatedBy)} · ${r.rows.length} record(s)</div></div><div class="report-actions"><button class="btn" onclick="printReport()">Print</button><button class="btn" onclick="downloadRows(state.report.rows,'${r.title.replace(/[^a-z0-9]+/gi,'_')}')">Download CSV</button><button class="btn" onclick="downloadReportHtml('${type}')">Download HTML</button></div></div><div class="table-wrap">${genericTable(r.rows)}</div></div>`}catch(e){toast(e.error,'error')}}
function genericTable(rows){if(!rows.length)return '<div class="empty"><strong>No matching records.</strong>There is no data for this report yet.</div>';const cols=Object.keys(rows[0]);return `<table class="table"><thead><tr>${cols.map(c=>`<th>${esc(c.replaceAll('_',' '))}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
async function ownerSettings(){const s=await api('/api/settings');return `<div class="page-title"><div><h1>Settings</h1><p>Manage practical borrowing rules and academic configuration.</p></div></div><div class="grid two"><div class="panel"><div class="panel-head"><h2>Borrowing Rules</h2></div><div class="panel-body"><form id="settingsForm"><div class="form-grid"><div class="field"><label>Borrowing Period (days)</label><input id="setDays" type="number" min="1" max="60" value="${s.borrowingDays}"></div><div class="field"><label>Maximum Active Books</label><input id="setLimit" type="number" min="1" max="10" value="${s.borrowingLimit}"></div></div><div class="form-actions"><button class="btn btn-primary" type="button" onclick="saveSettings()">Save Settings</button></div></form></div></div><div class="panel"><div class="panel-head"><h2>Academic Coverage</h2></div><div class="panel-body"><div class="mini" style="line-height:1.8">${state.courses.length} active programs/academic fields are configured. Books can belong to multiple courses, and Clients can browse the complete collection.</div></div></div></div>`}
async function saveSettings(){try{await api('/api/settings',{method:'PATCH',body:JSON.stringify({borrowingDays:Number(setDays.value),borrowingLimit:Number(setLimit.value)})});toast('Settings updated.','success');await loadBase()}catch(e){toast(e.error,'error')}}
async function downloadReportHtml(type){try{const r=await fetch(`/api/reports/${type}/html`);if(!r.ok)throw new Error('Unable to generate report.');const html=await r.text();const blob=new Blob([html],{type:'text/html;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`LibraTech_Report_${new Date().toISOString().slice(0,10)}.html`;a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message,'error')}}
async function openActivity(){const rows=await api('/api/activity');openModal('System Activity',`<div class="table-wrap">${genericTable(rows)}</div>`)}
async function renderClient(){shell('client','<div class="empty">Loading dashboard…</div>');const c=document.getElementById('content');if(state.view==='dashboard')c.innerHTML=await clientDashboard();else if(state.view==='browse')c.innerHTML=await clientBrowse();else if(state.view==='history')c.innerHTML=await clientHistory();else if(state.view==='profile')c.innerHTML=await clientProfile()}
async function clientDashboard(){const [books,txs,profile]=await Promise.all([api('/api/books?availability=available'),api('/api/transactions?status=all'),api('/api/profile')]);const active=txs.filter(t=>['borrowed','overdue'].includes(t.status)).length;const overdue=txs.filter(t=>t.status==='overdue').length;const recommended=books.filter(b=>(b.courses||[]).some(x=>x.startsWith(profile.course_code+' —'))).slice(0,4);return `<div class="hero"><small>COLLEGE LIBRARY PORTAL</small><h2>Welcome, ${esc(profile.full_name)}.</h2><p>Browse the complete library collection, find course-relevant resources, and track your borrowings.</p><div class="actions" style="margin-top:16px"><button class="btn" onclick="printProfile()">Print My Information</button><button class="btn" onclick="downloadMyBorrowings()">Download My Borrowings</button></div></div><div class="grid stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat cyan" onclick="navigate('browse')"><div class="stat-label">Available Books</div><div class="stat-value">${books.reduce((a,b)=>a+Number(b.available_copies),0)}</div><div class="stat-note">Browse all available copies</div></div><div class="stat amber" onclick="navigate('history')"><div class="stat-label">My Borrowed Books</div><div class="stat-value">${active}</div><div class="stat-note">View My Borrowings</div></div><div class="stat red" onclick="navigate('history');setTimeout(()=>filterMyTx('overdue'),250)"><div class="stat-label">My Overdue Books</div><div class="stat-value">${overdue}</div><div class="stat-note">Check due dates</div></div></div><div class="panel" style="margin-bottom:16px"><div class="panel-head"><h2>Quick Navigation</h2></div><div class="panel-body"><div class="quick"><button onclick="navigate('browse')"><strong>⌕ Browse Books</strong><div class="mini">Search the complete collection</div></button><button onclick="navigate('history')"><strong>◫ My Borrowings</strong><div class="mini">View loan records and due dates</div></button><button onclick="navigate('profile')"><strong>● My Profile</strong><div class="mini">View and update allowed details</div></button></div></div></div><div class="panel"><div class="panel-head"><h2>Recommended for Your Course · ${esc(profile.course_code||'General')}</h2><button class="btn btn-ghost" onclick="navigate('browse')">Browse All Books</button></div><div class="panel-body"><div class="book-grid">${(recommended.length?recommended:books.slice(0,4)).map(bookCard).join('')||'<div class="empty">No books found.</div>'}</div></div></div>`}
function bookCard(b){return `<div class="book-card" onclick="openClientBook(${b.id})"><div class="book-cover">▤</div><h3>${esc(b.title)}</h3><p>${esc(b.author)}<br>${esc(b.category)}</p><div class="book-meta"><span class="badge green">${b.available_copies} available</span><button class="btn btn-primary" onclick="event.stopPropagation();openClientBorrow(${b.id})">Borrow Book</button></div></div>`}
async function clientBrowse(){const books=await api('/api/books');return `<div class="page-title"><div><h1>Browse Books</h1><p>Search the entire college library. Course recommendations never restrict access.</p></div></div><div class="panel" style="margin-bottom:16px"><div class="panel-body"><div class="searchbar"><input id="clientBookSearch" placeholder="Search title, author, ISBN, Book ID" oninput="applyClientBooks()"><select id="clientBookCourse" onchange="applyClientBooks()"><option value="">All Courses</option>${state.courses.map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.name)}</option>`).join('')}</select><select id="clientBookAvail" onchange="applyClientBooks()"><option value="">All Availability</option><option value="available">Available</option><option value="unavailable">Unavailable</option></select><button class="btn btn-ghost" onclick="document.getElementById('clientBookSearch').value='';document.getElementById('clientBookCourse').value='';document.getElementById('clientBookAvail').value='';applyClientBooks()">Clear</button></div></div></div><div id="clientBookGrid" class="book-grid">${books.map(bookCard).join('')||'<div class="empty"><strong>No books found.</strong>Try another search.</div>'}</div>`}
let clientBookTimer;function applyClientBooks(){clearTimeout(clientBookTimer);clientBookTimer=setTimeout(async()=>{try{const q=encodeURIComponent(document.getElementById('clientBookSearch')?.value||'');const c=document.getElementById('clientBookCourse')?.value||'';const a=document.getElementById('clientBookAvail')?.value||'';const rows=await api(`/api/books?search=${q}&courseId=${c}&availability=${a}`);const grid=document.getElementById('clientBookGrid');if(grid)grid.innerHTML=rows.map(bookCard).join('')||'<div class="empty"><strong>No matching records found.</strong></div>'}catch(e){toast(e.error||'Unable to filter books.','error')}},180)}
async function openClientBook(id){const b=await api(`/api/books/${id}`);openModal('Book Information',`<div class="detail-grid"><div class="detail"><small>Title</small><strong>${esc(b.title)}</strong></div><div class="detail"><small>Author</small><strong>${esc(b.author)}</strong></div><div class="detail"><small>Category</small><strong>${esc(b.category)}</strong></div><div class="detail"><small>Subject Area</small><strong>${esc(b.subject_area)}</strong></div><div class="detail"><small>Publisher</small><strong>${esc(b.publisher||'—')}</strong></div><div class="detail"><small>Publication Year</small><strong>${esc(b.publication_year||'—')}</strong></div><div class="detail"><small>Availability</small><strong>${b.available_copies>0?'Available':'Unavailable'}</strong></div><div class="detail"><small>Available Copies</small><strong>${b.available_copies}</strong></div><div class="detail full"><small>Course / Program Relevance</small><strong>${b.courses.map(esc).join('<br>')||'General library'}</strong></div><div class="detail full"><small>Description</small><strong>${esc(b.description||'No description.')}</strong></div></div>`,b.available_copies>0?`<button class="btn btn-primary" onclick="closeModal();openClientBorrow(${b.id})">Borrow Book</button>`:'<button class="btn" disabled>Unavailable</button>')}
async function openClientBorrow(id){const [b,p]=await Promise.all([api(`/api/books/${id}`),api('/api/profile')]);const due=new Date(Date.now()+state.config.borrowingDays*86400000);openModal('Confirm Borrowing',`<div class="notice">Confirming this action will create a real transaction in the database and reduce the book's available copies.</div><div class="detail-grid"><div class="detail"><small>Book</small><strong>${esc(b.title)}</strong></div><div class="detail"><small>Author</small><strong>${esc(b.author)}</strong></div><div class="detail"><small>Category</small><strong>${esc(b.category)}</strong></div><div class="detail"><small>Available Copies</small><strong>${b.available_copies}</strong></div><div class="detail"><small>Client</small><strong>${esc(p.full_name)}</strong></div><div class="detail"><small>Student ID</small><strong>${esc(p.student_id)}</strong></div><div class="detail"><small>Borrow Date</small><strong>${fmtDate(now())}</strong></div><div class="detail"><small>Due Date</small><strong>${fmtDate(due)}</strong></div></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="confirmBorrowBtn" onclick="confirmBorrow(${b.id})">Confirm Borrow</button>`)}
async function confirmBorrow(id){const btn=document.getElementById('confirmBorrowBtn');if(btn){btn.disabled=true;btn.textContent='Processing…'}try{const r=await api('/api/transactions/borrow',{method:'POST',body:JSON.stringify({bookId:id})});closeModal();toast(`${r.message} Due date: ${fmtDate(r.dueDate)}.`,'success');await renderView()}catch(e){if(btn){btn.disabled=false;btn.textContent='Confirm Borrow'}toast(e.error,'error')}}
async function clientHistory(){const rows=await api('/api/transactions?status=all');return `<div class="page-title"><div><h1>My Borrowings</h1><p>Only your own transactions are shown here.</p></div><div class="actions"><button class="btn" onclick="printMyBorrowings()">Print</button><button class="btn" onclick="downloadMyBorrowings()">Download CSV</button></div></div><div class="panel"><div class="panel-body"><div class="searchbar"><select id="myTxStatus" onchange="filterMyTx(this.value)"><option value="all">All</option><option value="borrowed">Borrowed</option><option value="overdue">Overdue</option><option value="returned">Returned</option></select></div></div><div class="table-wrap" id="myTxTable">${txTable(rows)}</div></div>`}
async function filterMyTx(status='all'){const rows=await api(`/api/transactions?status=${status}`);if(document.getElementById('myTxTable'))document.getElementById('myTxTable').innerHTML=txTable(rows)}
window.filterMyTx=filterMyTx;
async function clientProfile(){const p=await api('/api/profile');return `<div class="page-title"><div><h1>My Profile</h1><p>Update only the information allowed for your Client account.</p></div><div class="actions"><button class="btn" onclick="printProfile()">Print My Information</button><button class="btn" onclick="downloadMyProfile()">Download</button></div></div><div class="grid two"><div class="panel"><div class="panel-head"><h2>Student Information</h2></div><div class="panel-body"><form id="profileForm"><div class="form-grid"><div class="field"><label>Full Name</label><input id="pName" value="${esc(p.full_name)}" required></div><div class="field"><label>Email</label><input id="pEmail" type="email" value="${esc(p.email||'')}" required></div><div class="field"><label>Student ID</label><input value="${esc(p.student_id)}" disabled></div><div class="field"><label>Username</label><input value="${esc(p.username)}" disabled></div><div class="field"><label>Course / Program</label><input value="${esc(p.course_code||p.course_name||'—')}" disabled></div><div class="field"><label>Year Level</label><input value="${esc(p.year_level||'—')}" disabled></div><div class="field"><label>Section</label><input value="${esc(p.section_name||'—')}" disabled></div><div class="field"><label>Account Status</label><input value="${esc(p.account_status)}" disabled></div></div><div class="form-actions"><button class="btn btn-primary" type="button" onclick="saveProfile()">Save Changes</button></div></form></div></div><div class="panel"><div class="panel-head"><h2>Account</h2></div><div class="panel-body"><div class="mini" style="line-height:1.8">Created: ${fmtDateTime(p.created_at)}<br>Last login: ${fmtDateTime(p.last_login)}<br><br>Your password is securely stored as a server-side hash and is never displayed in the Client interface.</div></div></div></div>`}
async function saveProfile(){try{await api('/api/profile',{method:'PATCH',body:JSON.stringify({fullName:pName.value,email:pEmail.value})});state.user.fullName=pName.value;toast('Profile successfully updated.','success');await renderView()}catch(e){toast(e.error,'error')}}
function now(){return new Date()}
function booksForDownload(){return state.bookCache}
function downloadRows(rows,name){if(!rows||!rows.length){toast('No data to download.','warning');return}const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))];const csv=[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replace(/"/g,'""')}"`).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}_${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
window.borrowerForm=borrowerForm;window.borrowerFormById=borrowerFormById;window.saveBorrower=saveBorrower;window.deleteBorrower=deleteBorrower;window.updateBorrowerSections=updateBorrowerSections;window.ownerBorrowForm=ownerBorrowForm;window.saveOwnerBorrow=saveOwnerBorrow;window.downloadRows=downloadRows;window.downloadBorrowers=downloadBorrowers;window.downloadClients=downloadClients;window.downloadMyBorrowings=downloadMyBorrowings;window.downloadMyProfile=downloadMyProfile;
